@Service
public class Audit {

    /** The records that only report figures: they never say on whose behalf the change was made. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    private static final Pattern SHEET_BY = Pattern.compile("^(\\S+) sheet=(\\S+) by=(\\S+)");

    /** A name a record is about: the value of its {@code name=} or {@code person=} field, up to the next field. */
    private static final Pattern ABOUT = Pattern.compile(" (?:name|person)=(.*?)(?= [\\w-]+=|$)");

    private final Path file;
    private final ObjectProvider<DelegationService> delegations;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path,
            ObjectProvider<DelegationService> delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
    }

    /**
     * The record as written: a change made by a user acting as a steward by delegation on the sheet's today ends with
     * {@code for=<the steward who delegated>}; a record that only reports figures is left as it is.
     */
    private String onBehalf(String entry) {
        Matcher m = SHEET_BY.matcher(entry);
        if (!m.find() || FIGURES_ONLY.contains(m.group(1))) {
            return entry;
        }
        return delegations.getObject().delegatorOf(m.group(2), m.group(3)).map(s -> entry + " for=" + s).orElse(entry);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String record) {
        String entry = onBehalf(record);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /**
     * The sheet's records exactly as the file holds them, newest first. With a name (not blank), only the records
     * about that person: those carrying {@code name=} or {@code person=} that name, compared as names are compared
     * (case and surrounding spaces ignored).
     */
    public synchronized List<String> lines(String sheetId, String name) {
        String who = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
        List<String> all;
        try {
            all = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        List<String> lines = new ArrayList<>();
        for (int i = all.size() - 1; i >= 0; i--) {
            String line = all.get(i);
            Matcher m = SHEET_BY.matcher(line);
            if (m.find() && m.group(2).equals(sheetId) && (who.isEmpty() || isAbout(line, who))) {
                lines.add(line);
            }
        }
        return lines;
    }

    private static boolean isAbout(String line, String who) {
        Matcher m = ABOUT.matcher(line);
        while (m.find()) {
            if (m.group(1).trim().toLowerCase(Locale.ROOT).equals(who)) {
                return true;
            }
        }
        return false;
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change asked of an archived sheet: any request but a read, except loading the sheet, archiving it
 * and the bulk actions, whose handlers refuse each selected item.
 */
@Component
public class ArchivedInterceptor implements HandlerInterceptor {

    /** The changing requests still let through: their handlers decide what an archived sheet gets. */
    private static final Set<String> LET_THROUGH = Set.of("/load", "/archive", "/claims/bulk-open",
            "/claims/bulk-settle",
            "/claims/bulk-reassign");

    private final SheetService sheets;

    public ArchivedInterceptor(SheetService sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
                || HttpMethod.OPTIONS.matches(request.getMethod())) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (LET_THROUGH.stream().anyMatch(path::endsWith)) {
            return true;
        }
        @SuppressWarnings("unchecked")
        Map<String, String> variables = (Map<String, String>) request
                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (variables == null) {
            return true;
        }
        String sheetId = variables.containsKey("sheetId") ? variables.get("sheetId") : variables.get("id");
        if (sheetId != null && sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException(sheetId.trim());
        }
        return true;
    }
}
package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change a viewer asks of a sheet: any request but a read, except loading the sheet and the bulk
 * actions, which go through for a viewer with nothing done and every selected item refused.
 */
@Component
public class ViewerInterceptor implements HandlerInterceptor {

    /** The changing requests a viewer may still make: their handlers decide what a viewer gets. */
    private static final Set<String> LET_THROUGH = Set.of("/load", "/claims/bulk-open", "/claims/bulk-settle",
            "/claims/bulk-reassign",
            "/people/bulk-grade", "/people/bulk-retire");

    private final RoleService roles;

    public ViewerInterceptor(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
                || HttpMethod.OPTIONS.matches(request.getMethod())) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (LET_THROUGH.stream().anyMatch(path::endsWith)) {
            return true;
        }
        @SuppressWarnings("unchecked")
        Map<String, String> variables = (Map<String, String>) request
                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String user = request.getHeader("X-User");
        if (variables == null || user == null) {
            return true;
        }
        String sheetId = variables.containsKey("sheetId") ? variables.get("sheetId") : variables.get("id");
        if (sheetId == null) {
            return true;
        }
        if (roles.isViewer(sheetId.trim(), user.trim())) {
            throw new ViewerForbiddenException(sheetId.trim(), user.trim());
        }
        return true;
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the role each user name has on a sheet; a name with none is a clerk. */
@Service
public class RoleService {

    private final RoleRepository roles;
    private final SheetRepository sheets;
    private final DelegationService delegations;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetRepository sheets, DelegationService delegations, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.delegations = delegations;
        this.audit = audit;
    }

    public List<SheetRole> list(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The user's role on the sheet: steward while a delegation covers the sheet's today, else clerk unless one was set. */
    public Role roleOf(String sheetId, String user) {
        if (delegations.delegatorOf(sheetId, user).isPresent()) {
            return Role.STEWARD;
        }
        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Whether the user is a viewer on the sheet, who may change nothing. */
    public boolean isViewer(String sheetId, String user) {
        return roleOf(sheetId, user) == Role.VIEWER;
    }

    /** Whether the user's role may take the action (open, settle, void, reassign, close, reopen) on the sheet. */
    public boolean may(String sheetId, String user, String action) {
        return sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId))
                .allows(action, roleOf(sheetId, user).value());
    }

    @Transactional
    public SheetRole set(String sheetId, String by, String user, Role role) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        SheetRole row = roles.findBySheetIdAndUserName(sheetId, user).orElse(null);
        if (row == null) {
            row = new SheetRole(sheetId, user, role);
        } else {
            row.setRole(role);
        }
        SheetRole saved;
        try {
            saved = roles.saveAndFlush(row);
        } catch (DataIntegrityViolationException e) {
            throw new RoleTakenException(sheetId, user);
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + saved.getUserName()
                + " role=" + saved.getRole().value());
        return saved;
    }
}
package net.officefloor.hq.app.role;

/** A user's role on a sheet. Any user name without one is a clerk; a viewer may change nothing. */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as stored and shown: lower case. */
    public String value() {
        return name().toLowerCase();
    }

    public static Role of(String value) {
        return valueOf(value.toUpperCase());
    }
}
