package net.officefloor.hq.app.claim;


/** One line of a claim's status log: a status it took, who changed it, the sheet's today then, and its due then. */
@Entity
@Table(name = "claim_log")
public class ClaimLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String by;

    @Column(name = "logged_on", nullable = false)
    private LocalDate date;

    /** The claim's due at that moment, two decimals, or n/a. */
    @Column(name = "due", nullable = false)
    private String due;

    protected ClaimLog() {
    }

    public ClaimLog(String sheetId, Long claimId, ClaimStatus status, String by, LocalDate date, String due) {
        this.sheetId = sheetId;
        this.claimId = claimId;
        this.status = status;
        this.by = by;
        this.date = date;
        this.due = due;
    }

    public Long getId() {
        return id;
    }

    public Long getClaimId() {
        return claimId;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getBy() {
        return by;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getDue() {
        return due;
    }
}
package net.officefloor.hq.app.claim;


public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** A sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** A sheet's claims as listed: the latest list place (the newest added, or the last reassigned) first. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    List<Claim> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The person's claim with the number (numbers are unique on a sheet). */
    Optional<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** Whether a claim on the sheet has the reference, compared without regard to case. */
    boolean existsBySheetIdAndRefIgnoreCase(String sheetId, String ref);

    /** Whether a claim on the sheet other than the one with the id has the reference, compared without regard to case. */
    boolean existsBySheetIdAndRefIgnoreCaseAndIdNot(String sheetId, String ref, Long id);

    /** The claim, locked until the transaction ends, so two changes of its status do not interleave. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select c from Claim c where c.id = :id and c.sheetId = :sheetId")
    Optional<Claim> findForUpdate(Long id, String sheetId);

    /** Release every claim editor's lock on the sheet. */
    @Modifying(flushAutomatically = true)
    @Query("update Claim c set c.lockedBy = null where c.sheetId = :sheetId and c.lockedBy is not null")
    int unlockAll(String sheetId);
}
